class View:
    def __init__(self):
        self.rows=[]; self.notes={}; self.loading=False; self.error=None; self.seq=0; self._latest_id=0; self._finished=False; self._latest_rows=[]
    def begin(self, query):
        self.seq+=1
        self.error=None; self.loading=False
        self._latest_id=self.seq; self._finished=False
        return self.seq
    def finish(self, request_id, rows):
        if request_id==self._latest_id and not self._finished:
            self._finished=True; self._latest_rows=rows; self.loading=False
            return True
        return False
    def copy_accepted_rows(self):
        return list(self._latest_rows)
